import{_ as e,o as a,c as s,ae as n}from"./chunks/framework.BzQXgbNp.js";const g=JSON.parse('{"title":"🔍 /invsee 玩家與假人背包管理系統","description":"","frontmatter":{},"headers":[],"relativePath":"Mc-InvSee-System.md","filePath":"Mc-InvSee-System.md"}'),o={name:"Mc-InvSee-System.md"};function l(r,t,i,d,c,p){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="🔍-invsee-玩家與假人背包管理系統" tabindex="-1">🔍 /invsee 玩家與假人背包管理系統 <a class="header-anchor" href="#🔍-invsee-玩家與假人背包管理系統" aria-label="Permalink to &quot;🔍 /invsee 玩家與假人背包管理系統&quot;">​</a></h1><p>Craft-Core 提供了原生 26.2 54-槽位實時雙向背包與裝備管理介面。無論是管理員進行維護與沒收，或是普通玩家管理自己創建的假人 (Bot)，皆可透由 <code>/invsee</code> 指令進行直觀操作。</p><hr><h2 id="🎮-指令與權限說明" tabindex="-1">🎮 指令與權限說明 <a class="header-anchor" href="#🎮-指令與權限說明" aria-label="Permalink to &quot;🎮 指令與權限說明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>適用對象</th><th>功能與權限</th></tr></thead><tbody><tr><td><code>/invsee &lt;玩家/假人名稱&gt;</code></td><td>普通玩家</td><td><strong>僅限查看與拿取自己擁有的假人</strong>（使用 <code>/bot</code> 召喚之 Bot）背包物品與裝備。</td></tr><tr><td><code>/invsee &lt;玩家/假人名稱&gt;</code></td><td>OP 管理員</td><td>可檢視與拿取全服所有線上/離線玩家及假人的背包、裝備、末影箱與狀態。</td></tr></tbody></table><hr><h2 id="📦-54-槽位介面版面配置-ui-layout" tabindex="-1">📦 54 槽位介面版面配置 (UI Layout) <a class="header-anchor" href="#📦-54-槽位介面版面配置-ui-layout" aria-label="Permalink to &quot;📦 54 槽位介面版面配置 (UI Layout)&quot;">​</a></h2><p>開啟 GUI 後，將呈現 6x9 (54 格) 大型箱子容器：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ Slot 0  ~ 35 ] 🎒 主背包 36 格空間 (快捷欄 + 物品欄)</span></span>
<span class="line"><span>[ Slot 36 ~ 39 ] 🛡️ 裝備欄位 (頭盔、胸甲、護腿、靴子)</span></span>
<span class="line"><span>[ Slot 40      ] 🗡️ 副手 (Offhand) 裝備格</span></span>
<span class="line"><span>[ Slot 41 ~ 43 ] 📊 玩家實時狀態 (❤️ 生命值 / 🍖 飽食度 / 💰 金幣餘額)</span></span>
<span class="line"><span>[ Slot 44      ] 🟣 末影箱切換按鈕 (一鍵切換 主背包 ↔ 末影箱)</span></span>
<span class="line"><span>[ Slot 45 ~ 53 ] 🔒 控制與隔離欄位</span></span></code></pre></div><hr><h2 id="⭐-特色與安全保護機制" tabindex="-1">⭐ 特色與安全保護機制 <a class="header-anchor" href="#⭐-特色與安全保護機制" aria-label="Permalink to &quot;⭐ 特色與安全保護機制&quot;">​</a></h2><ol><li><strong>實時雙向同步 (Two-way Realtime Sync)</strong>： 在 GUI 內移動、放置或拿出物品時，目標玩家/假人身上的物品會<strong>瞬間同步更新</strong>，無需關閉介面。</li><li><strong>末影箱切換 (Ender Chest Toggle)</strong>： 點擊 Slot 44 的 🟣 紫色末影水晶圖示，即可切換檢視與管理目標玩家的末影箱內容！</li><li><strong>離線 NBT 讀寫支援</strong>： 若目標玩家目前不居於線上記錄，系統自動解析 <code>PlayerData NBT</code> 進行離線讀寫。</li><li><strong>管理員沒收通知與日誌審核</strong>： 當管理員從普通玩家背包拿取或調整物品時，系統會自動在遊戲內向目標玩家發送黃字提醒，並寫入系統防作弊日誌 <code>logs.json</code>。</li></ol>`,12)])])}const u=e(o,[["render",l]]);export{g as __pageData,u as default};
